"""Bind source roadside tables to isolated native lamp/tree sprites and art states."""
from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,re,math,collections,numpy as np
import world_pack as wp
R=wp.ROOT;OUT='assets/world/overlays/roadside';PRE=R/'previews/roadside';CODES={0:'flat',3:'sw',6:'se',9:'nw',12:'ne'}
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def ref(f,record=None):return{'file':f,'sha256':wp.sha(R/f),'record':record or f+'.derivation.json'}
def source_tables():
 text=(R/'reference/OpenTTD/src/table/road_land.h').read_text(encoding='utf8');arrays={}
 for name,body in re.findall(r'static const DrawRoadTileStruct\s+(\w+)\[\]\s*=\s*\{(.*?)\};',text,re.S):arrays[name]=[{'sourceSpriteId':int(s,0),'sourceX':int(x),'sourceY':int(y)}for s,x,y in re.findall(r'MAKELINE\((0x[0-9a-f]+|\d+),\s*(\d+),\s*(\d+)\)',body)]
 tables={}
 for kind,name in [('StreetLights','lamps'),('Trees','trees')]:
  body=re.search(r'_roadside_'+name+r'\[\]\s*=\s*\{(.*?)\};',text,re.S)[1];symbols=re.findall(r'_road(?:side_nothing|_display_datas2_\d+)',body);tables[kind]=[{'connectionMask':i,'sourceTable':sym,'placements':arrays[sym]}for i,sym in enumerate(symbols)]
 return tables
def emit(id,im,srcs,op,extra):
 f=OUT+'/'+id+'.png';ar=np.array(im.convert('RGBA'));ar[ar[...,3]==0,:3]=0;Image.fromarray(ar).save(R/f);a={'id':id,'image':f,'width':128,'height':160,'format':'PNG','mode':'RGBA','sha256':wp.sha(R/f),'anchorPx':[64,144],'pivotUnity':[.5,.1],'border':[0,0,0,0],'category':'roadside-reusable-prop','sourceRequirementIds':['road-road','road-tram'],'derivedFrom':srcs,'operation':op,'nativeModelGeneration':False,'nativeUpscale':False,'actualModel':None,'actualQuality':None,'status':'produced-needs-actual-visual-review','unityValidated':False,'userArtAcceptance':'pending',**extra};wp.writej(Path(str(R/f)+'.derivation.json'),a);return a
def extract_props():
 src='source-art/world/roadside-lamps-native.png';raw=Image.open(R/src).convert('RGBA');ar=np.array(raw);assets=[]
 for ident,lo,hi,baseid in [('roadside-lamp-left',0,768,0x57f),('roadside-lamp-right',768,1536,0x57e)]:
  cell=ar[:,lo:hi].copy();cell[cell[...,3]<=8]=0;mask=cell[...,3]>128;yy,xx=np.where(mask);bottom=yy.max();contactx=int(np.median(xx[yy>=bottom-3]));bbox=Image.fromarray(cell[...,3]).getbbox();l,t,r,b=bbox;part=Image.fromarray(cell).crop(bbox);scale=64/part.height;target=(round(part.width*scale),64);part=part.resize(target,Image.Resampling.LANCZOS);sx=(contactx-l)*scale;sy=(bottom-t)*scale;at=[round(64-sx),round(144-sy)];canvas=Image.new('RGBA',(128,160));canvas.alpha_composite(part,tuple(at));a=emit(ident,canvas,[ref(src,src+'.generation.json')],'native physical lamp Alpha crop;remove source Alpha<=8 outer haze,clear Alpha0 hiddenRGB;preserve retained nativeRGB;proportional downsample to64pxphysical height;measured foot contact to fixed canvas;no repaint',{'sourceSpriteId':baseid,'sourceCropXYXY':[l+lo,t,r+lo,b],'sourceFootContactPx':[contactx+lo,int(bottom)],'formalVisibleTargetHeight':64,'uniformScale':scale,'pasteXY':at,'sourceAlphaCutoff':8,'sourceHiddenRGBDiscarded':True,'armDirectionScreen':'left'if baseid==0x57f else'right','state':'normal','sourceBoundingBoxWorld':[2,2,16]});assets.append(a)
 tree='assets/world/vegetation/mature/tree-07.png';q=load(R/'assets/world/vegetation/manifest.json');old=next(x for x in q['assets']if x['image']==tree);im=Image.open(R/tree).convert('RGBA');bbox=im.getchannel('A').getbbox();l,t,r,b=bbox;part=im.crop(bbox);scale=80/part.height;part=part.resize((round(part.width*scale),80),Image.Resampling.LANCZOS);at=[round(64-(old['anchorPx'][0]-l)*scale),round(144-(old['anchorPx'][1]-t)*scale)];canvas=Image.new('RGBA',(128,160));canvas.alpha_composite(part,tuple(at));assets.append(emit('roadside-tree',canvas,[ref(tree)],'direct reuse of existing native-painted poplar phenotype;uniform80pxheight downsample and existing root-anchor registration;not a new species/master',{'sourceSpriteId':0x1212,'sourceCropXYXY':list(bbox),'sourceFootContactPx':old['anchorPx'],'formalVisibleTargetHeight':80,'uniformScale':scale,'pasteXY':at,'state':'normal','sourceBoundingBoxWorld':[2,2,16],'treeIdentity':'new art uses existing poplar;source table provides one numeric treeSprite,not a botanical species'}))
 for a in list(assets):
  im=Image.open(R/a['image']).convert('RGBA');im.putalpha(im.getchannel('A').point(lambda v:round(v*.35)));assets.append(emit(a['id']+'-transparent',im,[ref(a['image'])],'explicit artwork transparency state0.35Alpha on the same registered native prop;preview treatment,not exact original-game palette emulation',{'sourceSpriteId':a['sourceSpriteId'],'state':'transparent','baseAssetId':a['id'],'alphaMultiplier':.35,'sourceTransparencyOption':'Trees'if a['sourceSpriteId']==0x1212 else'Houses','sourceBoundingBoxWorld':[2,2,16]}))
 return assets
def partialz(x,y,code):return{0:0,3:(x+1)//2,6:(y+1)//2,9:(16-y)//2,12:(16-x)//2}[code]
def point(x,y,code):return[256+(y-x)*8,192+(x+y)*4-partialz(x,y,code)*4]
def asset_for(assets,sprite,state='normal'):return next(a for a in assets if a['sourceSpriteId']==sprite and a['state']==state)
def draw_case(assets,case,kind='road',state='normal',suppress=False):
 code=case['effectiveSlopeCode'];mask=case['connectionMask'];f=f'assets/world/infrastructure/road-variants/{kind}-town-pavement-mask-{mask:02d}-slope-{CODES[code]}.png';base=Image.new('RGBA',(512,384));base.alpha_composite(Image.open(R/f).convert('RGBA'),(128,128));deps=[ref(f)]
 if not suppress:
  for p in sorted(case['placements'],key=lambda p:p['sourceX']+p['sourceY']):
   a=asset_for(assets,p['sourceSpriteId'],state);xy=p['contactPointPx'];base.alpha_composite(Image.open(R/a['image']).convert('RGBA'),(xy[0]-64,xy[1]-144));deps.append(ref(a['image']))
 return base,deps
def main():
 (R/OUT).mkdir(parents=True,exist_ok=True);PRE.mkdir(parents=True,exist_ok=True);assets=extract_props();tables=source_tables();bindings=[];cases=[]
 for roadside,rows in tables.items():
  for row in rows:
   b={'id':roadside+'-mask-'+str(row['connectionMask']),'roadside':roadside,'connectionMask':row['connectionMask'],'sourceTable':row['sourceTable'],'placements':row['placements'],'noDraw':not row['placements'],'sourceMaskMeaning':'index is (roadBits|tramBits).base(); source checks roadBits.Count()>1 separately','localArtReviewed':False};bindings.append(b)
   for code in CODES:
    placements=[{**p,'sourcePartialPixelZ':partialz(p['sourceX'],p['sourceY'],code),'contactPointPx':point(p['sourceX'],p['sourceY'],code),'normalAsset':asset_for(assets,p['sourceSpriteId'])['image'],'transparentAsset':asset_for(assets,p['sourceSpriteId'],'transparent')['image'],'anchorPx':[64,144],'sourceSortBounds':{'originXY':[p['sourceX'],p['sourceY']],'extentXYZ':[2,2,16]}}for p in row['placements']];cases.append({'roadside':roadside,'connectionMask':row['connectionMask'],'effectiveSlopeCode':code,'overlayPreviewCanvas':[512,384],'tileAnchorPx':[256,256],'roadPasteXY':[128,128],'placements':placements,'zRule':'source DrawRoadDetail asks GetSlopePixelZ at each actual road-edge coordinate; here source integer GetPartialPixelZ on post-foundation plane,plus caller world/foundation baseZ','sourceDepthSort':'independent2x2x16world bounding boxes;preview sorts x+y;Unity spatial sorting pending'})
 states={'normal':{'draw':True,'artState':'normal'},'transparent':{'draw':True,'artState':'transparent','previewAlpha':.35,'sourcePalette':'PALETTE_TO_TRANSPARENT;0.35previewAlpha is design treatment,not byte-equivalent original palette'},'invisible':{'draw':False,'sourceOption':'Trees for tree props,Houses for lamps'},'lowBridge':{'draw':False,'sourceTest':'bridgeHeight<TileMaxZ+2 forStreetLights; bridgeHeight<TileMaxZ+3 forTrees; equality permits drawing'},'noFullDetail':{'draw':False},'zoomBeyondDetail':{'draw':False},'roadBitCountAtMost1':{'draw':False,'includes':'tram-only tile even if union has>=2bits'},'roadWorks':{'draw':False,'sourceReason':'HasRoadWorks branch returns before decorative details'},'noPlacementInSourceTable':{'draw':False,'masks':[0,1,2,4,8,15]}}
 manifest={'schema':'roadside-source-prop-bindings.v1','createdAt':wp.now(),'assets':assets,'animations':[],'sourceMaskBindings':bindings,'sourcePlacementCases':cases,'stateContracts':states,'projection':{'canvas':[512,384],'tileAnchorPx':[256,256],'formalHeightStepPixels':32,'sourceTILE_SIZE':16,'worldToScreen':'x=256+(y-x)*8; y=192+(x+y)*4-GetPartialPixelZ(x,y,effectiveSlope)*4;source integer height rounding retained','sourceBoundingHeightWorld':16},'sourceFiles':[{'file':'reference/OpenTTD/src/'+p,'sha256':wp.sha(R/'reference/OpenTTD/src'/p)}for p in ['table/road_land.h','road_cmd.cpp','road_map.h','viewport.cpp','landscape.cpp','landscape.h','road_type.h','sprite.h']],'coverageMappings':[{'requirementId':rid,'files':[a['image']for a in assets],'variantName':'roadside StreetLights/Trees source mask coordinates,normal/transparent and visibility/lowbridge/detail guards','unionConnectionMasks':list(range(16)),'roadsideValues':[3,5],'postFoundationSlopeCodes':list(CODES),'normalReusablePropCount':3,'completeVariantCoverage':True}for rid in ['road-road','road-tram']],'nativeMastersAdded':1,'formalPNGs':len(assets),'userArtAcceptance':'pending','unityValidated':False,'status':'produced-needs-actual-visual-review'};wp.writej(R/OUT/'manifest.json',manifest);wp.writej(R/'docs/ROADSIDE_BINDINGS.json',{'schema':'roadside-bindings.v1','createdAt':wp.now(),'bindings':bindings,'sourcePlacementCases':cases,'stateContracts':states,'manifest':OUT+'/manifest.json','manifestSHA256':wp.sha(R/OUT/'manifest.json'),'complete':False,'failures':[],'userArtAcceptance':'pending','unityValidated':False})
 font=ImageFont.truetype(str(R/'assets/fonts/NotoSansSC-Variable.ttf'),14);pages=[]
 def contact(rows,name,kind='road',states=None):
  cols=4;cell=(300,260);out=Image.new('RGB',(1200,math.ceil(len(rows)/cols)*260+55),'#21483a');d=ImageDraw.Draw(out);d.text((12,8),name+' · 实际路面与独立原生道具叠层（等比缩小预览）',font=font,fill='#f5e8c9');deps=[]
  for k,c in enumerate(rows):
   st=states[k]if states else'normal';im,ss=draw_case(assets,c,kind,st if st=='transparent'else'normal',st in ['invisible','lowBridge','noFullDetail','zoomBeyondDetail','roadBitCountAtMost1','roadWorks']);im.thumbnail((296,222),Image.Resampling.LANCZOS);x=k%cols*300;y=k//cols*260+35;out.paste(im,(x+(300-im.width)//2,y),im);d.text((x+8,y+217),f'{c["roadside"]} mask{c["connectionMask"]:02d} / {CODES[c["effectiveSlopeCode"]]} / '+st,font=font,fill='#f5e8c9');deps+=ss
  f='previews/roadside/'+name+'.jpg';out.save(R/f,quality=96);wp.writej(Path(str(R/f)+'.derivation.json'),{'file':f,'sha256':wp.sha(R/f),'operation':'actual current native road/props registration and sort,aspect-downsample for contact only;no new scene painting','derivedFrom':deps,'nativeModelGeneration':False,'unityValidated':False});pages.append(f)
 for roadside in tables:
  active=[c for c in cases if c['roadside']==roadside and c['effectiveSlopeCode']==0 and c['placements']];contact(active,'roadside-'+roadside.lower()+'-all10masks')
 contact([c for c in cases if c['connectionMask']in[5,10]and c['placements']],'roadside-four-slopes')
 active=[c for c in cases if c['connectionMask']==10 and c['effectiveSlopeCode']==0];contact([c for c in active for _ in range(8)],'roadside-visibility-states',states=list(states)[:8]*2)
 # Mixed road+tram case requires actual road bits>1; pure tram guard remains false.
 contact([c for c in cases if c['connectionMask']in[5,10]and c['effectiveSlopeCode']==0],'roadside-road-plus-tram','tram')
 # Native dark/light matte inspection without any background repaint.
 out=Image.new('RGB',(768,340),'#21483a');d=ImageDraw.Draw(out)
 for k,a in enumerate([a for a in assets if a['state']=='normal']):
  for j,bg in enumerate(['#f1e7d1','#153b30']):
   tile=Image.new('RGBA',(128,160),bg);tile.alpha_composite(Image.open(R/a['image']).convert('RGBA'));out.paste(tile.convert('RGB'),(k*256+j*128,10));d.text((k*256+4,180),a['id'],font=font,fill='#f4e5c7')
 f='previews/roadside/roadside-deep-light-alpha.jpg';out.save(R/f,quality=96);pages.append(f)
 page='<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>道路路肩灯树与状态</title><style>body{background:#21483a;color:#f3e6ca;font:15px/1.5 system-ui;margin:20px}main{max-width:1200px;margin:auto}img{max-width:100%;height:auto}a{color:#d6b66b}</style><main><h1>路肩街灯与树木 · 源坐标及美术状态</h1><p>复用现有原生树，新增同一原生灯母图两种灯头朝向。32源mask绑定、160坡面定位组、正常/半透明PNG与不可见/低桥/远景/施工抑制合同。纯tram源条件不绘路边细节；混合road+tram按unionmask且roadCount>1使用。</p><p><a href="../../docs/ROADSIDE_BINDINGS.json">源码绑定</a> · <a href="../../docs/ROADSIDE_ART_DELIVERY.md">规格和状态</a></p>'
 for p in pages:page+='<h2>'+Path(p).stem+'</h2><img src="../../'+p+'" alt="'+Path(p).stem+'">'
 page+='</main>';(PRE/'index.html').write_text(page,encoding='utf8');print(json.dumps({'formalPNGs':len(assets),'sourceMaskBindings':len(bindings),'sourcePlacementCases':len(cases),'sourcePlacementCountFlat':sum(len(b['placements'])for b in bindings),'pages':pages,'manifestSHA256':wp.sha(R/OUT/'manifest.json')}))
if __name__=='__main__':main()
